// SkyShift service worker (generated by scripts/build.mjs; do not edit dist/sw.js).
// App shell: precached and versioned. Live data: network-first (handled in the app with
// IndexedDB fallbacks). HiPS sky tiles: cache-first. Navigations work offline.

const VERSION = '__VERSION__';
const SHELL = `skyshift-shell-${VERSION}`;
const RUNTIME = 'skyshift-runtime-v1';
const HIPS = 'skyshift-hips-v1';
const PRECACHE = __PRECACHE__;
const NETWORK_FIRST = /\/(config\.json|version\.json|data\/targets\.json)$/;

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(SHELL);
    await cache.addAll(PRECACHE.map((u) => new Request(u, { cache: 'reload' })));
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.filter((k) => k.startsWith('skyshift-shell-') && k !== SHELL).map((k) => caches.delete(k)));
    if (self.registration.navigationPreload) await self.registration.navigationPreload.enable().catch(() => {});
    await self.clients.claim();
  })());
});

self.addEventListener('message', (event) => {
  if (event.data?.type === 'SKIP_WAITING') self.skipWaiting();
});

async function trim(cacheName, max) {
  const c = await caches.open(cacheName);
  const keys = await c.keys();
  for (let i = 0; i < keys.length - max; i++) await c.delete(keys[i]);
}

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);

  // HiPS tiles for the sky atlas (CORS-enabled at IRSA): cache-first, bounded.
  if (url.hostname === 'irsa.ipac.caltech.edu' && url.pathname.startsWith('/data/hips/')) {
    // Aladin Lite opens a HiPS cube at its middle channel; in the SPHEREx DR1 cube channels 50/51
    // (0-based) are blank by design (IRSA docs), so serve the neighbouring valid channel 49 instead.
    let target = req;
    if (/spherex_allsky_cube\/.+_(50|51)\.png$/.test(url.pathname)) target = new Request(req.url.replace(/_(50|51)\.png$/, '_49.png'), { mode: 'cors' });
    event.respondWith((async () => {
      const c = await caches.open(HIPS);
      const hit = await c.match(target);
      if (hit) return hit;
      try {
        const res = await fetch(target);
        if (res.ok) { c.put(target, res.clone()); if (Math.random() < 0.05) trim(HIPS, 1500); }
        return res;
      } catch { return hit || Response.error(); }
    })());
    return;
  }
  if (url.origin !== self.location.origin) return; // S3 range reads and API calls are handled by the app
  if (url.pathname.endsWith('/api/relay')) return;

  if (req.mode === 'navigate') {
    event.respondWith((async () => {
      try {
        const pre = await event.preloadResponse;
        if (pre) return pre;
        const res = await fetch(req);
        return res;
      } catch {
        const c = await caches.open(SHELL);
        return (await c.match('./index.html')) || (await c.match('./')) || Response.error();
      }
    })());
    return;
  }

  if (NETWORK_FIRST.test(url.pathname)) {
    event.respondWith((async () => {
      try {
        const res = await fetch(req, { cache: 'no-cache' });
        if (res.ok) (await caches.open(RUNTIME)).put(req, res.clone());
        return res;
      } catch {
        return (await caches.match(req)) || Response.error();
      }
    })());
    return;
  }

  // Versioned shell assets: cache-first; anything else same-origin (e.g. Aladin Lite): stale-while-revalidate.
  event.respondWith((async () => {
    const hit = await caches.match(req, { ignoreSearch: false });
    if (hit) {
      if (!PRECACHE.some((p) => url.pathname.endsWith(p.replace(/^\.\//, '/')))) {
        fetch(req).then(async (res) => { if (res.ok) (await caches.open(RUNTIME)).put(req, res); }).catch(() => {});
      }
      return hit;
    }
    try {
      const res = await fetch(req);
      if (res.ok) (await caches.open(RUNTIME)).put(req, res.clone());
      return res;
    } catch {
      return Response.error();
    }
  })());
});
